# POST /api/sheets/{sheetId}/people/{personId}/watch — toggle whether the user watches the person (body:
# {user}): starts watching when they do not, stops when they do. Refused (400), storing nothing, when no
# user is given, the user is a viewer or the person is not on the sheet. A stored toggle is recorded in the audit file as
# PERSON_WATCHED or PERSON_UNWATCHED. A watcher is told (NOTIFY) of each claim of the person's settled,
# approved or re-settled.
validate:
  class: net.officefloor.hq.app.watch.ValidateWatch
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: toggle
toggle:
  class: net.officefloor.hq.app.watch.ToggleWatch
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.watch.AuditWatch
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
  govern: [ transaction ]
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadPerson {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
            PersonStore store, Out<Person> personOut) throws InvalidSheetException {
        Person person = null;
        try {
            person = store.find(sheetId.trim(), Long.parseLong(personId.trim()));
        } catch (NumberFormatException e) {
            // not an id: no such person
        }
        if (person == null) {
            throw new InvalidSheetException("No such person: " + personId);
        }
        personOut.set(person);
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;

/**
 * Refuses every change made from a screen showing a sheet as of a date: a request to {@code /api/} other than
 * a read, sent with the {@value #HEADER} header (the date the screen shows), answers 400 with the reason, and
 * reaches no endpoint, so it writes nothing to the store or the audit file. The as-of date belongs to the
 * screen; a change sent without it goes through as usual.
 */
@Component
public class AsOfGuard extends OncePerRequestFilter {

    /** The header a screen showing the sheet as of a date sends with each request. */
    public static final String HEADER = "X-As-Of";

    @Override
    protected boolean shouldNotFilter(HttpServletRequest request) {
        return !request.getRequestURI().startsWith("/api/") || "GET".equals(request.getMethod())
                || "HEAD".equals(request.getMethod()) || "OPTIONS".equals(request.getMethod());
    }

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
            throws ServletException, IOException {
        String asOf = request.getHeader(HEADER);
        if (asOf == null || asOf.isBlank()) {
            chain.doFilter(request, response);
            return;
        }
        response.setStatus(HttpStatus.BAD_REQUEST.value());
        response.setContentType("text/plain;charset=UTF-8");
        response.getOutputStream().write(("The sheet is shown as of " + asOf.trim() + ": clear the as-of date to change it")
                .getBytes(StandardCharsets.UTF_8));
    }
}
